1.1 从PubChem获取分子信息

rm(list = ls())

# 读取原始成分数据
ingredients_raw &lt;- read.xlsx("data/qfd_ingredients/raw.xlsx") |&gt;
  mutate(PubChem.CID = as.character(PubChem.CID)) |&gt;
  distinct(Abbreviation, PubChem.CID, .keep_all = TRUE) |&gt;
  arrange(Abbreviation)

# 从PubChem获取信息
source("utils.R")

properties &lt;- c("IUPACName", "MolecularFormula", "MolecularWeight", "SMILES")

unique_cids &lt;- unique(ingredients_raw$PubChem.CID)
cid_batches &lt;- split(unique_cids, ceiling(seq_along(unique_cids)/10))

plan(multisession, workers = availableCores() - 2)
with_progress({
  p &lt;- progressor(steps = length(cid_batches))
  chem_info &lt;- future_map_dfr(cid_batches, function(b) {
    p()
    fetch_batch(properties, b)
  })
})
plan(sequential)

ingredients &lt;- ingredients_raw |&gt;
  left_join(chem_info, by = c("PubChem.CID"="CID")) |&gt;
  mutate(across(where(is.character), trimws)) |&gt;
  mutate(MolecularWeight = as.numeric(MolecularWeight)) |&gt;
  arrange(Abbreviation, MolecularWeight)

save(ingredients,file = "data/qfd_ingredients/ingredients.RData")

2.2 PubChem BioAssay

rm(list = ls())

load("data/qfd_targets/targets.tmmc.RData")
load("data/qfd_ingredients/ingredients.RData")

targets.pubchem &lt;- targets.tmmc |&gt;
  dplyr::filter(SOURCE == "PubChem") |&gt;
  dplyr::distinct(ID,PROTEINID, .keep_all = TRUE) |&gt;
  left_join(ingredients, by =  c("ID" = "TMMC2.ID"), relationship = "many-to-many") |&gt;
  mutate(Class = "validated") |&gt;
  dplyr::select(No.,Abbreviation,Ingredient,Type,PubChem.CID, PROTEINID, Source = SOURCE, Score = SCORE, Class) |&gt;
  distinct(Abbreviation,PubChem.CID,PROTEINID, Source, Class, .keep_all = TRUE) |&gt;
  dplyr::filter(if_all(everything(), ~ !is.na(.x))) |&gt;
  arrange(No., PROTEINID)

