2.6 SwissTargetPrediction

rm(list = ls())

source("utils.R")

load("data/qfd_ingredients/ingredients.RData")

swiss &lt;- read_compound_target("data/qfd_targets/swiss/") |&gt;
  dplyr::rename(Probability = `Probability*`, 
                Common.name = `Common name`,
                Uniprot.ID = `Uniprot ID`) |&gt;
  separate_rows(Uniprot.ID, sep = "&") |&gt;
  separate_rows(Uniprot.ID, sep = " ") |&gt;
  dplyr::select(CID,Uniprot.ID, Probability) |&gt;
  distinct(CID, Uniprot.ID, .keep_all = TRUE) |&gt;
  dplyr::filter(!is.na(Uniprot.ID)) |&gt;
  distinct(CID, Uniprot.ID, .keep_all = TRUE) |&gt;
  mutate(
    CID = clean_cids(CID),
    Source = "SwissTargetPrediction",
    Class = "predicted"
    ) |&gt;
  dplyr::select(CID, Uniprot.ID,Source,Probability,Class)

targets.swiss &lt;- ingredients |&gt;
  left_join(swiss, by = c("PubChem.CID" = "CID"), relationship = "many-to-many") |&gt;
  dplyr::select(No.,Abbreviation,Ingredient,Type,PubChem.CID,Uniprot.ID, Source, Probability, Class) |&gt;
  distinct(Abbreviation,PubChem.CID, Uniprot.ID, Source, Class, .keep_all = TRUE) |&gt;
  dplyr::filter(if_all(everything(), ~ !is.na(.x))) |&gt;
  arrange(No., Uniprot.ID)

# Save processed SwissTargetPrediction targets
save(targets.swiss, file = "data/qfd_targets/targets.swiss.RData")

2.7 Super-PRED

rm(list = ls())

source("utils.R")

load("data/qfd_ingredients/ingredients.RData")

# known targets
super_known &lt;- read_compound_target("data/qfd_targets/super/known") |&gt;
  dplyr::select(CID, Uniprot.ID = `UniProt ID`) |&gt;
  dplyr::filter(!is.na(Uniprot.ID)) |&gt;
  distinct(CID, Uniprot.ID, .keep_all = TRUE) |&gt;
  mutate(Source = "SuperPred", Probability = "100%", `Model accuracy` = "100%", Class = "validated") |&gt;
  dplyr::select(CID, Uniprot.ID, Source, Probability, `Model accuracy`, Class)

# Predicted targets (Prob &gt;= 60, Model Accuracy &gt;= 85) (modify,70/90)
super_pred &lt;- read_compound_target("data/qfd_targets/super") |&gt;
  dplyr::select(CID, Uniprot.ID = `UniProt ID`, Probability, `Model accuracy`) |&gt;
  dplyr::filter(!is.na(Uniprot.ID)) |&gt;
  distinct(CID, Uniprot.ID, .keep_all = TRUE)|&gt;
  mutate(Source = "SuperPred", Class = "predicted") |&gt;
  dplyr::select(CID, Uniprot.ID, Source, Probability, `Model accuracy`, Class)

super &lt;- rbind(super_known, super_pred)

targets.super &lt;- ingredients |&gt;
  left_join(super, by = c("PubChem.CID" = "CID"), relationship = "many-to-many") |&gt;
  dplyr::select(No.,Abbreviation,Ingredient,Type,PubChem.CID,Uniprot.ID, Source, Probability, `Model accuracy`, Class) |&gt;
  distinct(Abbreviation,PubChem.CID, Uniprot.ID, Source, Class, .keep_all = TRUE) |&gt;
  dplyr::filter(if_all(everything(), ~ !is.na(.x))) |&gt;
