2.9 SEA

rm(list = ls())

source("utils.R")

load("data/qfd_ingredients/ingredients.RData")

# Process SEA results (confidence filters)
sea &lt;- read.csv("data/qfd_targets/sea/sea-results.xls") |&gt;
  mutate(CID = as.numeric(gsub("C","",Query.ID)), .before = 1) |&gt;
  arrange(CID) |&gt;
  mutate(CID = as.character(CID)) |&gt;
  dplyr::select(-Query.ID) |&gt;
  dplyr::filter(grepl("_HUMAN", Target.ID)) |&gt;
  distinct(CID, Target.ID, .keep_all = TRUE) |&gt;
  dplyr::filter(!is.na(Target.ID)) |&gt;
  mutate(Source = "SEA", Class = "predicted") |&gt;
