3.2 GeneCards

rm(list = ls())

genecards.hf &lt;- read.csv("data/chf_targets/genecards/genecards_hf.csv",skip = 4)

genecards.chf &lt;- read.csv("data/chf_targets/genecards/genecards_chf.csv",skip = 4)

genecards &lt;- rbind(genecards.hf,genecards.chf) |&gt;
  dplyr::group_by(Symbol) |&gt;
  dplyr::slice_max(Relevance.Score, n = 1, with_ties = FALSE) |&gt;
  dplyr::ungroup() |&gt;
  dplyr::filter(!is.na(Symbol)) |&gt;
  mutate(Source = "GeneCards")

nrow(genecards)

save(genecards,file = "data/chf_targets/genecards.RData")

3.3 TTD

rm(list = ls())

load("data/uniprot/uniprot_human_reviewed.RData")
uniprot_human_reviewed &lt;- uniprot_human_reviewed |&gt;
  mutate(Gene.Names.primary = trimws(Gene.Names.primary),
         Gene.Names = trimws(Gene.Names)) |&gt;
  dplyr::filter(Gene.Names.primary != "") |&gt;
  dplyr::select(Gene.Names.primary,Gene.Names) |&gt;
  separate_rows(Gene.Names, sep = "\\s+") |&gt;
  dplyr::filter(Gene.Names !="") |&gt;
  mutate(Gene.Names.primary = trimws(Gene.Names.primary),
         Gene.Names = trimws(Gene.Names))

ttd &lt;- read.xlsx("data/chf_targets/ttd/ttd.xlsx") |&gt;
  dplyr::distinct(Symbol) |&gt;
  left_join(uniprot_human_reviewed, 
            by = c("Symbol" = "Gene.Names"),
            relationship = "many-to-many") |&gt;
  dplyr::filter(!is.na(Gene.Names.primary)) |&gt;
  distinct(Gene.Names.primary) |&gt;
  dplyr::rename(Symbol = Gene.Names.primary) |&gt;
  mutate(Source="TTD")

nrow(ttd)

save(ttd,file = "data/chf_targets/ttd.RData")

